 if(a==='say'||a==='guide-say'){const l=current();const text=l?.text[lang]||Object.values(l?.text||{}).find(Boolean);if(text){await flush();await loader.say({packId:state.pack.id,line:structuredClone(l),language:lang});};return;}
 if(a==='record'){await record();return;}
 if(a==='import-audio'){$('#audio-file')?.click();return;}
 if(a==='play-take'||a==='booth-play'){const takes=current()?.takes?.[lang]||[],take=a==='booth-play'?takes.find(t=>t.used):takes.find(t=>t.id===el.dataset.take);if(take)try{await audio.play(take);}catch(e){toast(t(e.message),true);}return;}
 if(a==='use-take'){saveLine(l=>l.takes[lang].forEach(x=>x.used=x.id===el.dataset.take));loader.save('VOICE',`${current().id} ${lang} · used take changed`);notify('Take selected');render();return;}
 if(a==='trim'){trimId=trimId===el.dataset.take?null:el.dataset.take;render();return;}
 if(a==='delete-line'){const id=selected;edit(()=>state.lines=state.lines.filter(l=>l.id!==id));selected=state.lines.find(l=>l.pool===pool)?.id||'';loader.save('LINES',`deleted ${id}`);notify('Line deleted');render();return;}
 if(a==='prev-line'||a==='next-line'){const i=state.lines.findIndex(l=>l.id===selected),l=state.lines[i+(a==='next-line'?1:-1)];if(l){selected=l.id;pool=l.pool;}render();return;}
 if(a==='undo'||a==='redo'){audio.stop();if(history(a)){notify('Changes restored');loader.save('PACK',`${a} · snapshot restored`);if(!state.lines.find(l=>l.id===selected)){selected=state.lines[0]?.id||'';pool=state.lines[0]?.pool||'pomodoro.start';}if(state.pack&&view==='welcome')view='pack';render();}return;}
 if(a==='problems'){modalReturnFocus=el;modal('Problems',`<ul class="problems-list">${problems().map(p=>`<li>${escape(problemText(p))}</li>`).join('')||`<li>${tx('Nothing blocking your next idea.')}</li>`}</ul><p class="hint">${tx('Review missing translations before sharing. Text-only lines are allowed.')}</p>${btn('Share','nav-share',{ic:'arrow',cls:'primary'})}`);return;}
 if(a==='close-modal'){closeModal();return;}
 if(a==='wiring'){showWiring=!showWiring;if(showWiring){guide=null;view='wiring';location.hash='wiring';}render();return;}
 if(a==='wiring-labels'){showWiring=!showWiring;render();return;}
 if(a==='log'||a==='close-log'){drawer=!drawer;render();return;}
 if(a==='simulate'||a==='close-sim'){simMenu=!simMenu;render();return;}
 if(a==='connection'){simMenu=false;loader.connect(el.dataset.state);render();return;}
 if(a==='reset'||a==='empty'){sceneToken++;audio.stop();audio.stopPlayback();await reset(a==='empty');Object.keys(textureDraft).forEach(k=>delete textureDraft[k]);guide=null;selected='rain-01';pool='pomodoro.start';sceneId='scene-rain';lang='EN';translationLang='TH';filter='all';showWiring=false;view=a==='empty'?'welcome':'lines';simMenu=false;location.hash=view;notify('Demo reset');render();return;}
 if(a==='pack-language'){const codes=guide?.kind==='pack'?guide.draft.languages:state.pack.languages,code=el.dataset.lang;if(codes.includes(code)&&codes.length===1)return;const fn=()=>{const i=codes.indexOf(code);if(i>=0)codes.splice(i,1);else codes.push(code);};if(guide?.kind==='pack')fn();else{edit(fn);loader.save('MANIFEST',`languages ${codes.join(', ')}`);}render();return;}
 if(a==='add-language'){const code=$('#custom-code')?.value.trim().toUpperCase();if(!/^[A-Z]{2,3}(?:-[A-Z0-9]{2,4})?$/.test(code)){notify('Use a language code such as FR or ZH-CN.',true);return;}const codes=guide?.kind==='pack'?guide.draft.languages:state.pack.languages;if(codes.includes(code)){notify('Language already added');return;}if(guide?.kind==='pack')codes.push(code);else edit(()=>codes.push(code));notify('Language added');render();return;}
 if(a==='material'){material=el.dataset.material;render();return;}
 if(a==='pick-png'){$('#png-file').click();return;}
 if(a==='apply-texture'){
  const target=material,packId=state.pack.id;
  const rule={...(textureDraft[target]||state.textures[target]||{color:'#9583b7',tint:'#ffffff'})};
  if(rule.blob){const path=`textures/${target}-${globalThis.crypto?.randomUUID?.()||Date.now().toString(36)}.png`;await loader.putFile(packId,path,rule.blob);rule.file=path;delete rule.blob;}
  if(state.pack?.id!==packId)return;
  edit(()=>state.textures[target]={...rule,applied:true});delete textureDraft[target];
  loader.save('TEXTURE',`saved ${target} · mode=Shared`);await flush();
  if(state.pack?.id===packId)await loader.applyTexture({packId,material:target});render();return;
 }
 if(a==='revert-texture'){delete textureDraft[material];edit(()=>delete state.textures[material]);loader.save('TEXTURE',`reverted ${material} · original material restored`);notify('Texture reverted');render();return;}
 if(a==='filter'){filter=el.dataset.filter;render();return;}
 if(a==='scene'){sceneId=el.dataset.id;render();return;}
 if(a==='new-scene'){sceneId=`scene-${Date.now().toString(36)}`;edit(()=>state.scenes.push({id:sceneId,name:`${t('New scene')} ${state.scenes.length+1}`,rows:[{type:'Say',value:''}]}));loader.save('SCENE',`created ${sceneId}`);render();return;}
 if(a==='add-row'){mutateScene(s=>s.rows.push({type:'Say',value:''}));render();return;}
 if(a==='row-up'||a==='row-down'||a==='row-remove'){const i=+el.dataset.row;mutateScene(s=>{if(a==='row-remove')s.rows.splice(i,1);else{const n=i+(a==='row-up'?-1:1);if(n>=0&&n<s.rows.length)[s.rows[i],s.rows[n]]=[s.rows[n],s.rows[i]];}});render();return;}
 if(a==='play-scene'){await playScene();return;}
 if(a==='export-manifest'){download('manifest.json',manifest());return;}
