loader.bus.addEventListener('state',async()=>{audio.stopPlayback();await hydrate();selected=state.lines.find(l=>l.id===selected)?.id||state.lines[0]?.id||'';pool=state.lines.find(l=>l.id===selected)?.pool||pool;render();});
await hydrate();loader.watch();
