window.maker={studio:studioSnapshot,get state(){return structuredClone(state)},get view(){return view},get connection(){return loader.connection},get logs(){return [...loader.logs]},manifest,lineFile,get backend(){return loader.mode},get saveStatus(){return saveStatus}};
